// ---------- Animation particles ----------
var particles = [];
function makeIon(sign, x, y, kind) {
  var g = draw.group();
  g.circle(11).center(0, 0).fill(kind === 'na' ? '#7ab' : '#b7d94e').stroke({ color: '#333', width: 1 });
  g.text(sign).center(0, -1).font({ size: 11, family: 'sans-serif', anchor: 'middle', fill: '#111' });
