    particles.push({ el: b, vx: 0, vy: -(0.6 + Math.random() * 0.8), kind: 'bub', t: Math.random() * 100 });
  }
}
spawnParticles();
for (var p = 0; p < particles.length; p++) particles[p].el.hide();

var naFill = 0;
function tick() {
  if (!running) return;
  for (var i = 0; i < particles.length; i++) {
    var pt = particles[i];
    pt.t += 1;
    var cx = pt.el.cx(), cy = pt.el.cy();
    if (pt.kind === 'na') {
      cx += pt.vx;
      if (cx > 362 || cx < 218) { cx = 290 + (pt.vx > 0 ? 1 : -1) * 15; cy = 300 + Math.random() * 130; }
      pt.el.center(cx, cy);
    } else if (pt.kind === 'cl') {
      var dx = 290 - cx;
      cx += dx * 0.02;
      cy += 0.15;
      if (Math.abs(dx) < 18) { cx = 235 + Math.random() * 110; cy = 268 + Math.random() * 50; }
      pt.el.center(cx, cy);
    } else {
      cy += pt.vy;
      if (cy < 65) { cy = 300 + Math.random() * 40; cx = 295 + Math.random() * 40; }
      pt.el.center(cx, cy);
    }
  }
  // pink Na level slowly fills reservoir
  if (naFill < 80) {
    naFill += 0.06;
    naLevel.size(78, naFill).move(442, 414 - naFill);
  }
  requestAnimationFrame(tick);
}

