draw.text('NaCl').move(510, 166).font({ size: 15, family: 'sans-serif' });

// Iron screen: cylinder with curved bottom edge and slightly converging mesh
var screenG = draw.group();
(function () {
  var topY = 320, botY = 448, xL = 232, xR = 348, sag = 14;
  // outline with curved (elliptical) bottom
  screenG.path(
    'M ' + xL + ' ' + topY + ' L ' + xL + ' ' + botY +
    ' Q ' + ((xL + xR) / 2) + ' ' + (botY + sag) + ' ' + xR + ' ' + botY +
    ' L ' + xR + ' ' + topY
  ).fill('none').stroke({ color: '#222', width: 2.5 });
  // top rim ellipse hint (open cylinder mouth)
  screenG.ellipse(xR - xL, 12).center((xL + xR) / 2, topY).fill('none').stroke({ color: '#222', width: 1.5 });
  // vertical mesh lines: converge slightly toward center at the curved bottom
  for (var gx = xL + 10; gx < xR - 2; gx += 11) {
