  } else {
    cathL.attr('stroke', '#c0392b'); cathR.attr('stroke', '#c0392b');
    anode.attr('stroke', '#222'); anodeStem.attr('stroke', '#222');
    showPopup('Cathode (−) — reduction', 'Na⁺ + e⁻ → Na(l). Sodium ions pick up electrons at the iron cathode outside the screen. Liquid sodium is less dense than the melt, so it floats up through the side channel into the reservoir and drains out the Na outlet — the screen keeps it away from the Cl₂.');
  }
}
[anode, anodeStem].forEach(function (el) {
  el.css('cursor', 'pointer');
  el.on('click', function () { electrodeClick('anode'); });
  el.on('mousemove', function (e) { showTooltip('Anode (+): click for half-reaction', e); });
