  el.on('mousemove', function (e) { showTooltip('Cathode (−): click for half-reaction', e); });
  el.on('mouseleave', hideTooltip);
});
screenG.css('cursor', 'pointer');
screenG.on('mousemove', function (e) { showTooltip('Iron screen: keeps Na and Cl₂ apart', e); });
screenG.on('mouseleave', hideTooltip);
screenG.on('click', function () {
  showPopup('Iron screen', 'The mesh screen physically separates the anode (Cl₂ inside) from the cathode (Na outside). Because the products can never meet, they cannot recombine into NaCl.');
});

// ---------- Demo steps ----------
var steps = [
  { title: 'Cell anatomy', narration: 'Molten NaCl fills the cell. A central anode sits inside a cylindrical iron screen, with the cathode outside it; both connect to the voltage source. Note the two separate exits — Cl₂ at top, liquid Na at the side.' },
