// ---------- Animation particles ----------
var particles = [];
function makeIon(sign, x, y, kind) {
  var g = draw.group();
  g.circle(11).center(0, 0).fill(kind === 'na' ? '#7ab' : '#b7d94e').stroke({ color: '#333', width: 1 });
  g.text(sign).center(0, -1).font({ size: 11, family: 'sans-serif', anchor: 'middle', fill: '#111' });
  g.center(x, y);
  return g;
}
function spawnParticles() {
  // Na+ ions drifting outward toward cathodes
  for (var i = 0; i < 8; i++) {
    var side = i % 2 ? 1 : -1;
    var el = makeIon('+', 290 + side * (10 + Math.random() * 30), 300 + Math.random() * 130, 'na');
    particles.push({ el: el, vx: side * (0.35 + Math.random() * 0.3), vy: 0, kind: 'na', t: Math.random() * 100 });
  }
  // Cl− ions drifting inward toward anode
  for (var j = 0; j < 8; j++) {
    var el2 = makeIon('−', 240 + Math.random() * 100, 270 + Math.random() * 60, 'cl');
    particles.push({ el: el2, vx: 0, vy: 0, kind: 'cl', t: Math.random() * 100 });
  }
  // Cl2 bubbles rising inside the hood (spawn within the hood's interior)
  for (var k = 0; k < 10; k++) {
    var b = draw.circle(5 + Math.random() * 5).center(288 + Math.random() * 34, 260 + Math.random() * 45)
      .fill('#c8e04a').stroke({ color: '#8a9a2a', width: 1 }).opacity(0.85);
    particles.push({ el: b, vx: 0, vy: -(0.6 + Math.random() * 0.8), kind: 'bub', t: Math.random() * 100 });
  }
}
spawnParticles();
for (var p = 0; p < particles.length; p++) particles[p].el.hide();

var naFill = 0;
function tick() {
  if (!running) return;
  for (var i = 0; i < particles.length; i++) {
    var pt = particles[i];
    pt.t += 1;
    var cx = pt.el.cx(), cy = pt.el.cy();
    if (pt.kind === 'na') {
      cx += pt.vx;
      if (cx > 362 || cx < 218) { cx = 290 + (pt.vx > 0 ? 1 : -1) * 15; cy = 300 + Math.random() * 130; }
      pt.el.center(cx, cy);
    } else if (pt.kind === 'cl') {
      var dx = 290 - cx;
      cx += dx * 0.02;
      cy += 0.15;
      if (Math.abs(dx) < 18) { cx = 235 + Math.random() * 110; cy = 268 + Math.random() * 50; }
      pt.el.center(cx, cy);
    } else {
      cy += pt.vy;
      if (cy < 65) { cy = 262 + Math.random() * 40; cx = 288 + Math.random() * 34; }
      pt.el.center(cx, cy);
    }
  }
  // pink Na level slowly fills the reservoir through the channel
  if (naFill < 85) {
    naFill += 0.06;
    naLevel.size(44, naFill).move(480, 414 - naFill);
  }
  requestAnimationFrame(tick);
}

function trigger_electrolysisAnimation() {
  running = !running;
  document.getElementById('runBtn').textContent = running ? '⏸ Pause electrolysis' : '▶ Run electrolysis';
  for (var i = 0; i < particles.length; i++) particles[i].el.attr('display', running ? '' : 'none');
  if (running) tick();
}

